window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-billing-cost.html"]="<!-- Settings: Billing / Cost Control -->\n<style>\n.st-section{margin-bottom:28px;padding:20px;background:var(--card);border:1px solid var(--border);border-radius:12px}\n.st-section h3{margin:0 0 16px;font-size:15px;font-weight:700}\n.st-row{display:flex;align-items:center;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--border)}\n.st-row:last-child{border-bottom:none}\n.st-row .label{font-size:13px;font-weight:500}\n.st-row .desc{font-size:11px;color:var(--muted);margin-top:2px}\n.toggle{position:relative;width:44px;height:24px;cursor:pointer}\n.toggle input{display:none}\n.toggle .slider{position:absolute;inset:0;background:#cbd5e1;border-radius:12px;transition:.2s}\n.toggle input:checked+.slider{background:var(--accent)}\n.toggle .slider::after{content:'';position:absolute;width:18px;height:18px;border-radius:50%;background:#fff;top:3px;left:3px;transition:.2s}\n.toggle input:checked+.slider::after{left:23px}\n.cost-input{width:160px;padding:8px 10px;border:1px solid var(--border);border-radius:8px;font-size:14px;text-align:right;background:var(--bg);color:inherit}\n.cost-input:focus{outline:2px solid var(--accent);outline-offset:-1px}\n.preview-box{margin-top:16px;padding:14px;background:var(--bg);border:1px solid var(--border);border-radius:10px;font-size:12px;color:var(--muted);line-height:1.6}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\">\n    <div class=\"sn-title\">Organisasi</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-general')\">Umum</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-members')\">Anggota</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-roles')\">Role & Izin</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-tags')\">Tag</div>\n    <div class=\"sn-item\" onclick=\"go('settings/shift-hours')\">Jam Shift</div>\n    <div class=\"sn-title\">Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-assignments')\">Assignment</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-team-inbox')\">Tim Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-sla')\">SLA</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-csat')\">CSAT</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-macros')\">Makro</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-tickets')\">Tiket</div>\n    <div class=\"sn-title\">Channel</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-api')\">WhatsApp API</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-web')\">WhatsApp Web</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-widget')\">Widget</div>\n    <div class=\"sn-title\">Billing</div>\n    <div class=\"sn-item active\" onclick=\"go('settings/billing-cost')\">Kontrol Biaya</div>\n    <div class=\"sn-title\">Developer</div>\n    <div class=\"sn-item\" onclick=\"go('settings/developer-webhook')\">Webhook</div>\n  </aside>\n\n  <div class=\"settings-body\">\n    <h2 style=\"margin-bottom:4px\">Kontrol Biaya WhatsApp API</h2>\n    <p style=\"font-size:13px;color:var(--muted);margin-bottom:24px\">Atur batas estimasi biaya per percakapan. Berlaku hanya untuk channel WhatsApp API.</p>\n\n    <div class=\"st-section\">\n      <h3>💰 Batas Biaya per Percakapan</h3>\n      <div class=\"st-row\">\n        <div>\n          <div class=\"label\">Cap Estimasi Biaya</div>\n          <div class=\"desc\">Batas maksimum biaya per percakapan per bulan. Setelah mencapai batas, aturan di bawah berlaku.</div>\n        </div>\n        <div style=\"display:flex;align-items:center;gap:8px\">\n          <span style=\"font-size:13px;color:var(--muted)\">Rp</span>\n          <input type=\"number\" class=\"cost-input\" id=\"cfgCapPerChat\" min=\"0\" step=\"1000\" onchange=\"saveCostConfig()\">\n        </div>\n      </div>\n      <div class=\"preview-box\" id=\"capPreview\"></div>\n    </div>\n\n    <div class=\"st-section\">\n      <h3>🔔 Notifikasi Melebihi Batas</h3>\n      <div class=\"st-row\">\n        <div>\n          <div class=\"label\">Alert Ketika Melebihi Batas</div>\n          <div class=\"desc\">Tampilkan peringatan visual di percakapan ketika estimasi biaya melebihi cap.</div>\n        </div>\n        <label class=\"toggle\"><input type=\"checkbox\" id=\"cfgAlertEnabled\" onchange=\"saveCostConfig()\"><span class=\"slider\"></span></label>\n      </div>\n      <div class=\"preview-box\">Ketika aktif, agen akan melihat banner kuning ⚠️ \"Biaya percakapan telah melebihi batas\" di area chat.</div>\n    </div>\n\n    <div class=\"st-section\">\n      <h3>🚫 Blokir Pengiriman Saat Melebihi Batas</h3>\n      <div class=\"st-row\">\n        <div>\n          <div class=\"label\">Blokir Kirim Pesan Saat Melebihi Batas</div>\n          <div class=\"desc\">Jika aktif, agen tidak dapat mengirim pesan lagi di percakapan yang sudah melebihi cap biaya bulanan.</div>\n        </div>\n        <label class=\"toggle\"><input type=\"checkbox\" id=\"cfgBlockOnExceed\" onchange=\"saveCostConfig()\"><span class=\"slider\"></span></label>\n      </div>\n      <div class=\"preview-box\">Ketika aktif, composer pesan akan diganti dengan banner merah: \"Batas biaya percakapan tercapai. Pesan tidak dapat dikirim.\" Pengiriman template pesan tetap diizinkan.</div>\n    </div>\n\n    <div style=\"display:flex;gap:8px;margin-top:8px\">\n      <button class=\"btn primary\" onclick=\"saveCostConfig();showToast('Pengaturan biaya disimpan')\">Simpan Perubahan</button>\n      <button class=\"btn\" onclick=\"resetCostConfig()\">Reset ke Default</button>\n    </div>\n  </div>\n</div>\n\n<script>\nfunction initCostSettings(){\n  const cfg=(DB.costConfig)||{capPerChat:50000,alertEnabled:true,blockOnExceed:false};\n  document.getElementById('cfgCapPerChat').value=cfg.capPerChat;\n  document.getElementById('cfgAlertEnabled').checked=cfg.alertEnabled;\n  document.getElementById('cfgBlockOnExceed').checked=cfg.blockOnExceed;\n  updateCapPreview();\n}\nfunction updateCapPreview(){\n  const cap=parseInt(document.getElementById('cfgCapPerChat').value)||0;\n  const rate=358;\n  const maxBubbles=cap>0?Math.floor(cap/rate):0;\n  const capFmt='Rp '+cap.toLocaleString('id-ID');\n  document.getElementById('capPreview').innerHTML=\n    `<b>Preview:</b> Cap ${capFmt}/bulan = maksimal <b>${maxBubbles} bubble</b> per percakapan (${rate}/bubble).<br>`+\n    (cap>0?`Jika percakapan sudah mengirim ≥${maxBubbles} bubble bulan ini, aturan alert/blokir berlaku.`:'<span style=\"color:var(--danger)\">Cap diset ke 0 — tidak ada batasan.</span>');\n}\nfunction saveCostConfig(){\n  DB.costConfig={\n    capPerChat:parseInt(document.getElementById('cfgCapPerChat').value)||0,\n    alertEnabled:document.getElementById('cfgAlertEnabled').checked,\n    blockOnExceed:document.getElementById('cfgBlockOnExceed').checked,\n  };\n  saveStore();\n  updateCapPreview();\n}\nfunction resetCostConfig(){\n  DB.costConfig={capPerChat:50000,alertEnabled:true,blockOnExceed:false};\n  saveStore();\n  initCostSettings();\n  showToast('Pengaturan direset ke default');\n}\ndocument.getElementById('cfgCapPerChat').addEventListener('input',updateCapPreview);\ninitCostSettings();\n</script>\n";
